#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
install_presentv2.py - Present, round two, as ONE installer.

    python install_presentv2.py <path-to-T_Industries_SIREN_v1.html>

WHAT IT INSTALLS
  1  settings        the Present ... menu becomes seven verbs; camera framing,
                     motion and decisions get one visible home in the Studio.
  2  buildenter      the tile pill reads "Open" in Build and goes inside the
                     diagram; coming back restores Build, the deck and the stop.
  3  slidelist       the deck gets a second rendering - a searchable vertical
                     rail - off the same container, the same builder, one move.
  4  dragundo        rectangles are draggable on the plane with snapping and
                     guides, and the deck gets its own undo/redo stack.
  5  cardsindiagram  a content slide can live INSIDE a walkthrough, with the
                     same card model, the same editor and the same renderer;
                     Docs text colour applies inside a card.
  6  output          the deck also exports as real editable PowerPoint, and a
                     step or a card can reveal itself one press at a time.
  7  integration     the defects that exist only once the six meet - see below.

THE INTEGRATION PASS
  * removing a slide no longer claims "there is no undo for this"; the deck
    has an undo stack now and it covers exactly that.
  * the deck search reaches the content slides inside a diagram, not just the
    ones on the plane, so it can find the whole deck it is a list of.
  * the deck list and the exported file agree on how many slides there are:
    a diagram stop that carries content slides says "+N", and the count line
    reads "3 slides . 8 exported".
  * text colour and highlight survive into PowerPoint - every run used to be
    written in the deck's foreground, so .pptx was the one file that disagreed
    with the screen and the PDF.
  * "Reveal one line at a time" now works for a card inside a diagram. On the
    plane the reveal hides DOM; on the stage the card is the exported slide
    drawn as a picture, so the picture takes a reveal limit. Everything is
    still laid out and only the painting is withheld, so nothing moves.

GUARANTEES
  * every edit is anchor-guarded and must match EXACTLY the expected number of
    times; on ANY drift nothing at all is written and the file is untouched.
  * idempotent: run it twice and the second run reports ALREADY INSTALLED and
    writes nothing.
  * atomic: the new text goes to a temporary file in the same directory and is
    then os.replace()d over the target.
"""

import io
import os
import sys
import json
import tempfile

SENTINEL = 'function mapStopCards(view) {'


def sanity(text, original_length):
    """The shapes this installer promises, checked before anything is written."""
    checks = [
        # 1 - settings
        ('the " . in use" suffix is gone from the ... menu', 'inUse(' not in text),
        ('the settings have one visible home', text.count('id="presentPlaybackSettings"') == 1),
        ('the three selects are still the model',
            text.count('id="presentCameraMode"') == 1
            and text.count('id="presentTransition"') == 1
            and text.count('id="presentDecisionMode"') == 1),
        ('the resting Present bar still holds its seven controls',
            all(text.count('id="%s"' % name) == 1 for name in
                ['presentMapButton', 'presentPrevButton', 'presentNextButton', 'presentMoreButton',
                 'presentSidebarToggle', 'presentDimButton', 'presentExitButton'])),
        # 2 - buildenter
        ('the tile pill knows both words', text.count('function mapTileOpenLabel(') == 1
            and text.count('function mapUpdateTileOpenLabels(') == 1),
        ('going inside a diagram remembers Build', text.count('mapBuildResume = mapBuilding;') == 1),
        # 3 - slidelist
        ('the deck has two renderings off one container',
            text.count('function mapRenderRoute()') == 1
            and text.count('id="mapRouteItems"') == 1
            and text.count('id="mapRouteViewButton"') == 1),
        ('every move goes through one seam', text.count('function mapReorderRoute(') == 1),
        # 4 - dragundo
        ('the plane can move a rectangle',
            all(text.count('function %s(' % name) == 1 for name in
                ['mapDragTargetFor', 'mapDragMove', 'mapDragEnd', 'mapDragCancel', 'mapPlaceObjects'])),
        ('the deck has its own history',
            all(text.count('function %s(' % name) == 1 for name in
                ['scheduleMapHistory', 'mapStepHistory', 'mapApplySnapshot', 'mapRenderHistoryButtons'])
            and text.count('id="mapUndoButton"') == 1 and text.count('id="mapRedoButton"') == 1),
        ('history is wired at every deck mutation', text.count('scheduleMapHistory()') >= 10),
        # 5 - cardsindiagram
        ('a card can be hosted inside a walkthrough', text.count('mapCardEditorHost') > 1),
        ('one card model, one slide renderer', text.count('function mapCardSlideSvg(') == 1),
        # 6 - output
        ('the deck exports as PowerPoint', text.count('function mapExportRoutePptx(') == 1
            and text.count('function mapChooseDeckExport(') == 1),
        ('a step can reveal itself', text.count('function presentationRevealTotal(') == 1
            and text.count('presentRevealStep') > 5),
        # 7 - integration
        ('the deck knows what a stop carries', text.count('function mapStopCards(') == 1),
        ('PowerPoint can write a run colour', text.count('function mapPptxRunHex(') == 1),
        ('a card picture can be drawn part-revealed',
            text.count('function mapSlideFlowRevealTotal(') == 1
            and text.count('function mapCardSlideSvg(card, width, height, revealShown)') == 1),
        ('nothing still claims removing a slide cannot be undone',
            'There is no undo for this' not in text),
        ('the file grew', len(text) > original_length),
    ]
    return [name for name, ok in checks if not ok]


def main():
    if len(sys.argv) != 2:
        sys.stdout.write('usage: python install_presentv2.py <target.html>\n')
        return 2
    target = sys.argv[1]
    with io.open(target, encoding='utf-8', newline='') as handle:
        text = handle.read()
    original_length = len(text)

    if SENTINEL in text:
        sys.stdout.write('ALREADY INSTALLED - %s carries Present round two. Nothing was written.\n' % target)
        return 0

    edits = json.loads(_DATA)
    problems = []
    for name, label, old, new, count in edits:
        found = text.count(old)
        if found != count:
            problems.append('  %-14s %-62s found %d, expected %d' % (name, label[:62], found, count))
            continue
        text = text.replace(old, new, count)

    if problems:
        sys.stdout.write('ABORT - the file has drifted from the expected shape. Nothing was written.\n')
        for line in problems:
            sys.stdout.write(line + '\n')
        return 1

    failed = sanity(text, original_length)
    if failed:
        sys.stdout.write('ABORT - post-patch sanity failed. Nothing was written.\n')
        for name in failed:
            sys.stdout.write('  - ' + name + '\n')
        return 1

    directory = os.path.dirname(os.path.abspath(target)) or '.'
    handle, temporary = tempfile.mkstemp(dir=directory, suffix='.tmp')
    os.close(handle)
    try:
        with io.open(temporary, 'w', encoding='utf-8', newline='') as out:
            out.write(text)
        os.replace(temporary, target)
    except Exception:
        if os.path.exists(temporary):
            os.remove(temporary)
        raise

    sys.stdout.write('OK  %s\n' % target)
    sys.stdout.write('    %d edits applied, %d -> %d characters\n' % (len(edits), original_length, len(text)))
    return 0


